{"operationName":"login","variables":{"username":"koala.ocbuu@gmail.com","password":"Behieu123@","isRedTabGlobal":false},"query":"query login($username: String!, $password: String!, $anonCartGuid: String, $checkFor247Account: Boolean, $isRedTabGlobal: Boolean) {
