        clothing_type
        shopping_preferences
        denim_style
        birth_date {
          month
          year
        }
      }
      graduationYear
      student
      country {
        isocode
        name
      }
      lastRetailStoreId
    }
    merged
    mergeMessage
    storeUpdateMerged
    refreshTime
  }
}
"}

{"operationName":"getFavoriteItems","variables":{"offset":0,"limit":11},"query":"query getFavoriteItems($offset: Int, $limit: Int) {
  getFavoriteItems(offset: $offset, limit: $limit) {
    entries {
      addedDate
      product {
        channels
        altText
        baseOptions {
          selected {
            code
            comingSoon
            customizable
            displaySizeDescription
            findInStoreEligible
            flxCustomization
            soldIndividually
            soldOutForever
            upc
            url
            variantOptionQualifiers {
              name
            }
          }
          variantType
        }
        baseProduct
        code
        colorGroup
        colorName
        images {
          format
          imageType
          url
        }
        merchantBadge
        name
        price {
          currencyIso
          formattedValue
          priceType
          regularPrice
          regularPriceFormattedValue
          softPrice
          softPriceFormattedValue
          value
        }
        promotionalBadge
        returnable
        sku
        stock {
          stockLevel
          stockLevelStatus
        }
        sustainability
        url
      }
    }
    totalCount
  }
}
"}

