{"operationName":"getGooglePayData","variables":{"guid":"0dcacf75-a6a4-48d2-98ae-85d565e66e12"},"query":"query getGooglePayData($guid: String!) {
  getGooglePayData(guid: $guid) {
    merchantInfo {
      merchantId
      merchantName
    }
    allowedPaymentMethods {
      type
      parameters {
        allowedAuthMethods
        allowedCardNetworks
        billingAddressRequired
        billingAddressParameters {
          format
          phoneNumberRequired
        }
      }
      tokenizationSpecification {
        type
        parameters {
          gateway
          gatewayMerchantId
        }
      }
    }
    transactionInfo {
      totalPriceStatus
      totalPrice
      totalPriceLabel
      currencyCode
      countryCode
      displayItems {
        type
        label
        price
        status
      }
    }
    shippingOptionParameters {
      defaultSelectedOptionId
      shippingOptions {
        description
        id
        label
      }
    }
    callbackIntents
    shippingAddressRequired
    shippingAddressParameters {
      phoneNumberRequired
      allowedCountryCodes
    }
    emailRequired
    shippingOptionRequired
  }
}
"}

